cd /luxon && cat > test/duration/tmp_normalize.test.js <<'EOF'
import { Duration } from "../../src/luxon";
const units = ["years", "quarters", "months", "weeks", "days", "hours", "minutes", "seconds", "milliseconds"];

test("Duration#normalize can convert all unit pairs", () => {
  const bad = [];
  for (const big of units) {
    for (const small of units) {
      if (big === small) continue;
      for (const accuracy of ["casual", "longterm"]) {
        const d = Duration.fromObject({ [big]: 1, [small]: 1, conversionAccuracy: accuracy });
        const n = d.normalize();
        const expected = d.as("milliseconds");
        const actual = n.as("milliseconds");
        if (!Number.isFinite(actual) || Math.abs(actual - expected) > 1e-3) {
          bad.push(
            `${accuracy} ${big}+${small}: ${JSON.stringify(d.toObject())} -> ${JSON.stringify(
              n.toObject()
            )} (as ms ${actual} vs ${expected})`
          );
        }
      }
    }
  }
  console.log(bad.join("\n"));
  expect(bad).toEqual([]);
});

test("Duration#normalize rolls quarters up and down", () => {
  expect(Duration.fromObject({ years: 1, quarters: 1 }).normalize().toObject()).toEqual({
    years: 1,
    quarters: 1
  });
  expect(Duration.fromObject({ years: 1, quarters: 5 }).normalize().toObject()).toEqual({
    years: 2,
    quarters: 1
  });
  expect(Duration.fromObject({ quarters: 1, seconds: 1 }).normalize().toObject()).toEqual({
    quarters: 1,
    seconds: 1
  });
  expect(
    Duration.fromObject({ quarters: 1, seconds: 91 * 24 * 3600 }).normalize().toObject()
  ).toEqual({ quarters: 2 });
  expect(
    Duration.fromObject({ quarters: 1, seconds: 1, conversionAccuracy: "longterm" })
      .normalize()
      .toObject()
  ).toEqual({ quarters: 1, seconds: 1 });
  expect(
    Duration.fromObject({ years: 1, quarters: 1, conversionAccuracy: "longterm" })
      .normalize()
      .toObject()
  ).toEqual({ years: 1, quarters: 1 });
});
EOF
